public:
    int rectangleArea(vector<vector<int>>& rectangles) {
        long long MOD = 1000000007;
        set<int> xs_set;
        for (auto& r : rectangles) {
            xs_set.insert(r[0]);
            xs_set.insert(r[2]);
        }
        vector<int> xs(xs_set.begin(), xs_set.end());
        long long total_area = 0;
        for (size_t i = 0; i + 1 < xs.size(); i++) {
            long long x1 = xs[i], x2 = xs[i + 1];
            long long width = x2 - x1;
            vector<pair<int, int>> intervals;
            for (auto& r : rectangles) {
                if (r[0] <= x1 && r[2] >= x2) {
                    intervals.push_back({r[1], r[3]});
                }
            }
            sort(intervals.begin(), intervals.end());
            long long covered_y = 0;
            int cur_bottom = -1;
            for (auto& p : intervals) {
                cur_bottom = max(cur_bottom, p.first);
                if (p.second > cur_bottom) {
                    covered_y += p.second - cur_bottom;
                    cur_bottom = p.second;
                }
            }
            total_area = (total_area + covered_y * width) % MOD;
        }
        return total_area;
    }
