class Solution {
    public int rectangleArea(int[][] rectangles) {
        long MOD = 1_000_000_007L;
        TreeSet<Integer> xsSet = new TreeSet<>();
        for (int[] r : rectangles) {
            xsSet.add(r[0]);
            xsSet.add(r[2]);
        }
        List<Integer> xs = new ArrayList<>(xsSet);
        long totalArea = 0;
        for (int i = 0; i + 1 < xs.size(); i++) {
            long x1 = xs.get(i), x2 = xs.get(i + 1);
            long width = x2 - x1;
            List<int[]> intervals = new ArrayList<>();
            for (int[] r : rectangles) {
                if (r[0] <= x1 && r[2] >= x2) {
                    intervals.add(new int[]{r[1], r[3]});
                }
            }
            intervals.sort((a, b) -> Integer.compare(a[0], b[0]));
            long coveredY = 0;
            int curBottom = -1;
            for (int[] interval : intervals) {
                curBottom = Math.max(curBottom, interval[0]);
                if (interval[1] > curBottom) {
                    coveredY += interval[1] - curBottom;
                    curBottom = interval[1];
                }
            }
            totalArea = (totalArea + coveredY * width) % MOD;
        }
        return (int) totalArea;
    }
}

var rectangleArea = function(rectangles) {
    const MOD = 1000000007n;
    const xs = Array.from(new Set(rectangles.flatMap(r => [r[0], r[2]]))).sort((a, b) => a - b);
    let totalArea = 0n;
    for (let i = 0; i + 1 < xs.length; i++) {
        const x1 = xs[i], x2 = xs[i + 1];
        const width = BigInt(x2 - x1);
        const intervals = [];
        for (const [rx1, ry1, rx2, ry2] of rectangles) {
            if (rx1 <= x1 && rx2 >= x2) {
                intervals.push([ry1, ry2]);
            }
        }
        intervals.sort((a, b) => a[0] - b[0]);
        let coveredY = 0n;
        let curBottom = -1;
        for (const [y1, y2] of intervals) {
            curBottom = Math.max(curBottom, y1);
            if (y2 > curBottom) {
                coveredY += BigInt(y2 - curBottom);
                curBottom = y2;
            }
        }
        totalArea = (totalArea + coveredY * width) % MOD;
    }
    return Number(totalArea);
